// @name Emergency card
// @background #ffffff
// @refresh 86400
// An "in case of emergency" card for a frame by the door or on the fridge:
// who lives here, their allergies (first and loudest), the people to call,
// their conditions and medications, their doctor, insurance and address.
// Everything is in the scene's settings, and a field left empty shows
// nothing. The type is as large as the panel lets it be, and on e-paper the
// card stays readable with the power off.
//
// Each contact's phone is a link: a tap shows its QR code on the frame, for
// a phone to dial. Where there is room, the QR code is on the card itself
// (the scene's data/qr nodes make one for each of the first three contacts).
import { cardOf, telOf } from './card'
import type { Card } from './card'
import { captionOf, contactWords, dropNote, fitLine, fitsLine, hasQr, lineHeight, planCard, textClass } from './fit'
import type { Room } from './fit'

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

type Theme = {
  page: string
  band: string
  bandLabel: string
  accent: string
  muted: string
  box: string
  boxLabel: string
  boxText: string
  button: string
}

const THEMES: Record<string, Theme> = {
  color: {
    page: 'bg-white text-[#111827]',
    band: 'bg-[#b91c1c] text-white',
    bandLabel: 'text-[#fecaca]',
    accent: 'text-[#b91c1c]',
    muted: 'text-[#4b5563]',
    box: 'bg-[#fef2f2] border-[#b91c1c]',
    boxLabel: 'text-[#b91c1c]',
    boxText: 'text-[#111827]',
    button: 'bg-[#b91c1c] text-white',
  },
  high: {
    page: 'bg-white text-black',
    band: 'bg-black text-white',
    bandLabel: 'text-white',
    accent: 'text-black',
    muted: 'text-black',
    box: 'bg-white border-black',
    boxLabel: 'text-black',
    boxText: 'text-black',
    button: 'bg-black text-white',
  },
}

// Color e-paper (Spectra's six inks): the high-contrast card with its red in
// the panel's own red ink (dither.nim's measured table), so nothing is
// dithered into confetti.
THEMES.inks = {
  ...THEMES.high,
  band: 'bg-[#6b1119] text-white',
  accent: 'text-[#6b1119]',
  box: 'bg-white border-[#6b1119]',
  boxLabel: 'text-[#6b1119]',
  button: 'bg-[#6b1119] text-white',
}

const themeOf = (app): Theme => {
  if (highContrast(app)) return THEMES.high
  if ((app.state.contrast || 'auto') === 'auto' && app.frame.paper === true) return THEMES.inks
  return THEMES.color
}

// The QR code the scene's data/qr node made for contact i (the first three).
const qrOf = (app, i: number) => {
  const ref = app.config[`qr${i + 1}`]
  return ref && ref.__frameosType === 'imageRef' && ref.width > 0 ? ref : null
}

const px = (n: number) => `${Math.round(n * 100) / 100}px`

// ---------------------------------------------------------------- icons

const Warning = ({ size, className }) => (
  <svg className={`w-[${size}px] h-[${size}px] shrink-0 ${className}`} viewBox="0 0 24 24">
    <path d="M13,14H11V10H13M13,18H11V16H13M1,21H23L12,2L1,21Z" fill="currentColor" />
  </svg>
)

const Cross = ({ size, className }) => (
  <svg className={`w-[${size}px] h-[${size}px] ${className}`} viewBox="0 0 24 24">
    <path d="M19,3H5C3.89,3 3,3.89 3,5V19A2,2 0 0,0 5,21H19A2,2 0 0,0 21,19V5C21,3.89 20.1,3 19,3M18,14H14V18H10V14H6V10H10V6H14V10H18V14Z" fill="currentColor" />
  </svg>
)

// ---------------------------------------------------------------- the card's parts

// The emergency number: a link, so a tap shows its QR code for a phone.
const Dial = ({ number, className, children }) => {
  const tel = telOf(number)
  return tel ? <a href={tel} className={className}>{children}</a> : <div className={className}>{children}</div>
}

// The band at the top: the title, and the number to call.
const Header = ({ t, card, W, hh, pad }) => {
  const numberSize = Math.round(hh * 0.46)
  const labelSize = Math.max(9, Math.round(hh * 0.17))
  const numberW = card.number ? Math.max(card.number.length * 0.62 * numberSize, 9 * 0.7 * labelSize) : 0
  const titleW = W - 2 * pad - (card.number ? numberW + pad : 0)
  const titleSize = fitLine(card.title, titleW, Math.round(hh * 0.42), Math.max(10, Math.round(hh * 0.24)))
  return (
    <div className={`flex flex-row items-center w-full h-[${hh}px] shrink-0 px-[${pad}px] gap-[${pad}px] ${t.band}`}>
      <div className={`flex-1 min-w-0 ${textClass(titleSize, 'font-bold')}`}>{card.title}</div>
      {card.number ? (
        <Dial number={card.number} className="flex flex-col items-end shrink-0">
          <span className={`${textClass(labelSize, 'font-bold')} ${t.bandLabel}`}>EMERGENCY</span>
          <span className={textClass(numberSize, 'font-bold')}>{card.number}</span>
        </Dial>
      ) : null}
    </div>
  )
}

// Who the card is about: the name, and what is known at a glance.
const Person = ({ card, s }) => (
  <div className={`flex flex-col gap-[${s.lineGap}px]`}>
    {card.name ? <div className={s.name}>{card.name}</div> : null}
    {card.facts.length ? (
      <div className={s.body}>
        {card.facts.map((fact, i) => (
          <>
            {i > 0 ? ' · ' : ''}
            {`${fact.label}: `}
            <span className="font-bold">{fact.value}</span>
          </>
        ))}
      </div>
    ) : null}
  </div>
)

const Label = ({ section, s, className }) => <div className={`${s.label} ${className}`}>{section.label.toUpperCase()}</div>

// The allergies: in a box with a thick border, larger and bold.
const Loud = ({ section, s, t }) => (
  <div className={`flex flex-col w-full border-[${s.border}px] p-[${s.boxPad}px] rounded-[${Math.round(s.f * 0.35)}px] ${t.box}`}>
    <div className={`flex flex-row items-center gap-[${2 * s.labelGap}px]`}>
      <Warning size={s.icon} className={t.boxLabel} />
      <div className={`flex-1 min-w-0 ${s.label} ${t.boxLabel}`}>{section.label.toUpperCase()}</div>
    </div>
    <div className={`flex flex-col gap-[${s.lineGap}px] mt-[${s.labelGap}px]`}>
      {section.lines.map((line) => <div className={`${s.loud} ${t.boxText}`}>{line}</div>)}
    </div>
  </div>
)

// One contact: the name and relation, and the phone (a link: a tap shows its
// QR code), with its QR code beside them where the card has them there.
const ContactRow = ({ contact, s, t, words, qr }) => (
  <div className={`flex flex-row items-center gap-[${s.qrGap}px]`}>
    <div className={`flex flex-col w-[${words}px]`}>
      {contact.name || contact.relation ? (
        <div className={s.bold}>
          {contact.name}
          {contact.relation ? <span className={`font-normal ${t.muted}`}>{contact.name ? ` (${contact.relation})` : contact.relation}</span> : null}
        </div>
      ) : null}
      {contact.phone && contact.tel ? (
        <a href={contact.tel} className={`${s.phone} whitespace-nowrap`}>{contact.phone}</a>
      ) : contact.phone ? (
        <div className={`${s.phone} whitespace-nowrap`}>{contact.phone}</div>
      ) : null}
    </div>
    {qr ? <img src={qr.ref} className={`w-[${px(qr.side)}] h-[${px(qr.side)}] shrink-0`} /> : null}
  </div>
)

// The QR codes in a row under the list, each with its contact's name.
const CodeRow = ({ codes, s, side }) => (
  <div className={`flex flex-row gap-[${s.qrGap}px]`}>
    {codes.map((code) => (
      <div className={`flex flex-col items-center w-[${px(side)}]`}>
        <img src={code.ref} className={`w-[${px(side)}] h-[${px(side)}]`} />
        <div className={`${s.label} mt-[${s.labelGap}px] w-full text-center truncate`}>{code.caption}</div>
      </div>
    ))}
  </div>
)

const Contacts = ({ section, s, t, room, plan, width, refs }) => {
  const words = contactWords(plan.place, plan.qr, width, s)
  const codes = section.contacts
    .map((contact, j) => (hasQr(room, plan.qr, contact, j) ? { ref: refs[j], caption: captionOf(contact, j) } : null))
    .filter((code) => code)
  return (
    <div className="flex flex-col">
      <Label section={section} s={s} className={t.accent} />
      <div className={`flex flex-col gap-[${s.contactGap}px] mt-[${s.labelGap}px]`}>
        {section.contacts.map((contact, j) => (
          <ContactRow contact={contact} s={s} t={t} words={words}
            qr={plan.place === 'beside' && hasQr(room, plan.qr, contact, j) ? { ref: refs[j], side: plan.qr } : null} />
        ))}
        {plan.place === 'below' && codes.length ? <CodeRow codes={codes} s={s} side={plan.qr} /> : null}
      </div>
    </div>
  )
}

const Plain = ({ section, s, t }) => (
  <div className="flex flex-col">
    <Label section={section} s={s} className={t.accent} />
    <div className={`flex flex-col gap-[${s.lineGap}px] mt-[${s.labelGap}px]`}>
      {section.lines.map((line) => <div className={s.body}>{line}</div>)}
    </div>
  </div>
)

const SectionBlock = ({ section, s, t, room, plan, width, refs }) =>
  section.loud ? <Loud section={section} s={s} t={t} />
    : section.contacts ? <Contacts section={section} s={s} t={t} room={room} plan={plan} width={width} refs={refs} />
      : <Plain section={section} s={s} t={t} />

// The person, then the sections in one column or two, then what had no room.
const Body = ({ card, plan, room, t, refs }) => {
  const s = plan.sizes
  const columns = plan.columns.filter((column) => column.length > 0)
  return (
    <div className={`flex flex-col w-[${room.width}px] gap-[${s.sectionGap}px]`}>
      {card.name || card.facts.length ? <Person card={card} s={s} /> : null}
      {columns.length > 1 ? (
        <div className={`flex flex-row items-start gap-[${room.width - 2 * plan.columnWidth}px]`}>
          {columns.map((column) => (
            <div className={`flex flex-col w-[${plan.columnWidth}px] gap-[${s.sectionGap}px]`}>
              {column.map((section) => <SectionBlock section={section} s={s} t={t} room={room} plan={plan} width={plan.columnWidth} refs={refs} />)}
            </div>
          ))}
        </div>
      ) : columns.length === 1 ? (
        <div className={`flex flex-col w-full gap-[${s.sectionGap}px]`}>
          {columns[0].map((section) => <SectionBlock section={section} s={s} t={t} room={room} plan={plan} width={plan.columnWidth} refs={refs} />)}
        </div>
      ) : null}
      {plan.dropped.length ? <div className={`${s.label} ${t.muted}`}>{dropNote(plan.dropped)}</div> : null}
    </div>
  )
}

// Nothing filled in yet: how to fill the card, and on a touch screen a
// button that opens the scene's settings.
const Empty = ({ t, size }) => {
  const f = Math.max(11, Math.round(size / 26))
  const openSettings = () => {
    if (typeof frameos.dispatch === 'function') frameos.dispatch('sceneSettings')
  }
  return (
    <div className={`flex flex-col items-center justify-center gap-[${Math.round(f * 0.8)}px] text-center`}>
      <Cross size={Math.round(f * 3.2)} className={t.accent} />
      <div className={textClass(Math.round(f * 1.4), 'font-bold')}>This card is empty</div>
      <div className={`${textClass(f)} ${t.muted}`}>Open the scene's settings to fill in this card: allergies, emergency contacts, medications and more. Only what you fill in shows.</div>
      <div className={`${textClass(f, 'font-bold')} px-[${f}px] py-[${Math.round(f * 0.5)}px] rounded-[${Math.round(f * 0.4)}px] ${t.button}`}
        onClick={openSettings}>
        Fill in the card
      </div>
    </div>
  )
}

// The body sizes the type may take, by the panel's shorter side: from `lo`
// to `hi`, and down to `least` only when the allergies and the contacts
// alone need it.
const typeRange = (side: number) => ({
  least: 9,
  lo: Math.max(12, Math.round(side * 0.02)),
  hi: Math.max(14, Math.round(side * 0.075)),
})

// ---------------------------------------------------------------- a rectangle

const flatCard = (app, t: Theme, card: Card, W: number, H: number) => {
  const side = Math.min(W, H)
  const pad = Math.round(Math.max(6, Math.min(48, side * 0.035)))
  const refs = [0, 1, 2].map((i) => qrOf(app, i))
  const scale = app.frame.scale || 1
  // The QR codes are drawn at their own size (a pixel of the code a pixel of
  // the panel), and only where the panel is not small.
  const firstQr = refs.find((ref) => ref)
  const qr = side >= 360 && firstQr ? firstQr.width / scale : 0
  const roomUnder = (band: number): Room => ({
    width: W - 2 * pad,
    height: H - band - 2 * pad,
    twoColumns: W >= H * 1.2 && W >= 560,
    columnGap: Math.round(pad * 1.5),
    qr,
    qrRows: refs.map((ref) => !!ref),
  })
  const range = typeRange(side)
  let hh = Math.round(Math.max(30, Math.min(160, side * 0.13)))
  let room = roomUnder(hh)
  let plan = card.empty ? null : planCard(card, room, range.least, range.lo, range.hi)
  // A card with little on it has large type: the band grows with it, so the
  // title still reads first.
  const grown = plan ? Math.min(Math.round(side * 0.2), Math.round(plan.sizes.f * 3)) : 0
  if (plan && grown > hh) {
    hh = grown
    room = roomUnder(hh)
    plan = planCard(card, room, range.least, range.lo, range.hi)
  }
  return (
    <div className={`flex flex-col w-full h-full overflow-hidden ${t.page}`}>
      <Header t={t} card={card} W={W} hh={hh} pad={pad} />
      <div className={`flex-1 min-h-0 flex flex-col p-[${pad}px] overflow-hidden`}>
        {plan ? (
          <Body card={card} plan={plan} room={room} t={t} refs={refs} />
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center">
            <div className={`w-[${Math.min(room.width, Math.round(side * 1.1))}px]`}>
              <Empty t={t} size={side} />
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------- a circle

// The title in a band over the arc at the top, the card in the square inside
// the circle, the emergency number in the arc at the bottom. No QR codes: a
// tap on a phone shows one.
const roundCard = (app, t: Theme, card: Card, W: number, H: number) => {
  const cx = W / 2
  const cy = H / 2
  const R = Math.min(W, H) / 2 - 12
  const side = Math.floor(R * Math.SQRT2)
  const top = Math.round(cy - side / 2)
  const left = Math.round(cx - side / 2)
  const chord = (y: number) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - (y - cy) * (y - cy))))
  const gap = Math.round(R * 0.04)
  // The title as large as fits the arc it sits in.
  const titleBottom = top - gap
  let titleSize = Math.round(R * 0.11)
  const titleMin = Math.max(10, Math.round(R * 0.06))
  while (titleSize > titleMin && !fitsLine(card.title, chord(titleBottom - lineHeight(titleSize)) - 8, titleSize)) titleSize--
  const titleTop = titleBottom - lineHeight(titleSize)
  const titleW = Math.max(40, chord(titleTop) - 8)
  const numberSize = Math.round(R * 0.1)
  const numberTop = top + side + gap
  const numberW = chord(numberTop + lineHeight(numberSize))
  const room: Room = { width: side, height: side, twoColumns: false, columnGap: 0, qr: 0, qrRows: [] }
  // A round screen is a small, dense one (1.75" to 2.1"): larger type, and
  // the allergies and the contacts before the rest.
  const range = { least: 12, lo: 15, hi: Math.max(15, Math.round(side * 0.08)) }
  const plan = card.empty ? null : planCard(card, room, range.least, range.lo, range.hi)
  // What fits sits in the middle of the circle, where it is widest.
  const middle = !plan || plan.fits ? 'justify-center' : ''
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <div className={`absolute left-0 top-0 w-[${W}px] h-[${top - Math.round(gap / 2)}px] ${t.band}`} />
      <div className={`absolute left-[${Math.round(cx - titleW / 2)}px] top-[${titleTop}px] w-[${titleW}px] text-center ${textClass(titleSize, 'font-bold')} text-white`}>
        {card.title}
      </div>
      <div className={`absolute left-[${left}px] top-[${top}px] w-[${side}px] h-[${side}px] flex flex-col ${middle} overflow-hidden`}>
        {plan ? (
          <Body card={card} plan={plan} room={room} t={t} refs={[]} />
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center">
            <Empty t={t} size={side * 1.25} />
          </div>
        )}
      </div>
      {card.number ? (
        <div className={`absolute left-[${Math.round(cx - numberW / 2)}px] top-[${numberTop}px] w-[${numberW}px] flex flex-row justify-center`}>
          <Dial number={card.number} className={`flex flex-row items-end gap-[${gap}px] ${t.accent}`}>
            <span className={textClass(Math.round(numberSize * 0.5), 'font-bold')}>EMERGENCY</span>
            <span className={textClass(numberSize, 'font-bold')}>{card.number}</span>
          </Dial>
        </div>
      ) : null}
    </div>
  )
}

export function get(app, context) {
  const t = themeOf(app)
  const card = cardOf(app.state)
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  if (context?.round === true) return roundCard(app, t, card, W, H)
  return flatCard(app, t, card, W, H)
}

