// What the card says, read from the scene's settings: who it is about, the
// sections in the order a helper reads them (allergies first), and the
// emergency contacts. Nothing here draws; app.tsx lays it out.

export const DEFAULT_TITLE = 'In case of emergency'
export const DEFAULT_NUMBER = '112'

export type Contact = { name: string; relation: string; phone: string; tel: string }

export type Section = {
  key: string
  label: string
  lines: string[]
  // Allergies: the first section, in a box of its own, in larger bold type.
  loud?: boolean
  // Emergency contacts: drawn as contacts (a name, a phone, a QR code).
  contacts?: Contact[]
}

export type Card = {
  title: string
  number: string
  name: string
  facts: { label: string; value: string }[]
  sections: Section[]
  empty: boolean
}

// The sections in the order they show: allergies and contacts first, then
// what a paramedic reads next, then the rest.
export const SECTIONS: { key: string; label: string }[] = [
  { key: 'allergies', label: 'Allergies' },
  { key: 'contacts', label: 'Emergency contacts' },
  { key: 'conditions', label: 'Medical conditions' },
  { key: 'medications', label: 'Medications' },
  { key: 'doctor', label: 'Doctor' },
  { key: 'insurance', label: 'Insurance' },
  { key: 'address', label: 'Address' },
  { key: 'notes', label: 'Notes' },
]

// A field's text as the lines it was typed in: white space made single, empty
// lines left out.
export const linesOf = (value: unknown): string[] =>
  String(value ?? '')
    .split(/\r?\n/)
    .map((line) => line.replace(/\s+/g, ' ').trim())
    .filter((line) => line !== '')

const textOf = (value: unknown): string => linesOf(value).join(' ')

// A phone number: digits with the usual punctuation, at least three digits.
export const isPhone = (part: string): boolean =>
  part.replace(/\D/g, '').length >= 3 && /^[+(\d][\d\s().\-\/]*$/.test(part)

// The number to dial: "+32 470 12 34 56" is "tel:+32470123456".
export const telOf = (phone: string): string => {
  const kept = phone.replace(/[^\d+]/g, '')
  const digits = kept.replace(/\+/g, '')
  return digits ? `tel:${kept.startsWith('+') ? '+' : ''}${digits}` : ''
}

// One contact line, "Name, relation, phone". The phone is the last part that
// is one; a line with no commas may end in its number ("Sam 555 0100").
export const parseContact = (line: string): Contact => {
  const parts = line.split(',').map((part) => part.trim()).filter((part) => part !== '')
  let phoneAt = -1
  for (let i = parts.length - 1; i >= 0 && phoneAt < 0; i--) {
    if (isPhone(parts[i])) phoneAt = i
  }
  let phone = phoneAt >= 0 ? parts[phoneAt] : ''
  const rest = parts.filter((_, i) => i !== phoneAt)
  if (!phone && rest.length > 0) {
    const last = rest[rest.length - 1]
    const trailing = /^(.*?)[\s:]*(\+?\(?\d[\d\s().\-\/]{4,}\d)$/.exec(last)
    if (trailing) {
      phone = trailing[2]
      if (trailing[1].trim()) rest[rest.length - 1] = trailing[1].trim()
      else rest.pop()
    }
  }
  return { name: rest[0] ?? '', relation: rest.slice(1).join(', '), phone, tel: telOf(phone) }
}

export const parseContacts = (value: unknown): Contact[] => linesOf(value).map(parseContact)

// The card from the scene's state. A field that is empty shows nothing.
export const cardOf = (state: Record<string, any>): Card => {
  const name = textOf(state.name)
  const facts: { label: string; value: string }[] = []
  const born = textOf(state.born)
  if (born) facts.push({ label: 'Born', value: born })
  const blood = textOf(state.bloodType)
  if (blood) facts.push({ label: 'Blood type', value: blood })
  const donor = textOf(state.organDonor)
  if (donor) facts.push({ label: 'Organ donor', value: donor })
  const sections: Section[] = []
  for (const { key, label } of SECTIONS) {
    if (key === 'contacts') {
      const contacts = parseContacts(state.contacts)
      if (contacts.length > 0) sections.push({ key, label, lines: [], contacts })
      continue
    }
    const lines = linesOf(state[key])
    if (lines.length > 0) sections.push({ key, label, lines, loud: key === 'allergies' })
  }
  const title = textOf(state.title) || DEFAULT_TITLE
  // The emergency number shows unless it is cleared; 112 until it is set.
  const number = state.emergencyNumber === undefined || state.emergencyNumber === null ? DEFAULT_NUMBER : textOf(state.emergencyNumber)
  return { title, number, name, facts, sections, empty: !name && facts.length === 0 && sections.length === 0 }
}

