// How large the card's type can be: the largest body size at which every
// section fits the panel, measured with the frame's own typesetting
// (frameos.measureText), with no word broken across two lines and every
// phone number on one. app.tsx draws with exactly the sizes, classes and
// widths worked out here.
import type { Card, Contact, Section } from './card'

// A text size and its line height as classes: what is measured is what is drawn.
export const lineHeight = (size: number) => Math.round(size * 1.2)
export const textClass = (size: number, weight = '') =>
  `text-[${size}px] leading-[${lineHeight(size)}px]${weight ? ` ${weight}` : ''}`
export const lineHeightOf = (className: string): number => Number(/leading-\[(\d+)px\]/.exec(className)?.[1] ?? 0)

export type Sizes = {
  f: number
  body: string
  bold: string
  label: string
  loud: string
  name: string
  phone: string
  labelGap: number
  lineGap: number
  sectionGap: number
  contactGap: number
  boxPad: number
  border: number
  icon: number
  qrGap: number
}

// Every size on the card from the body size f.
export const sizesFor = (f: number): Sizes => {
  const label = Math.min(f, Math.max(10, Math.round(f * 0.7)))
  return {
    f,
    body: textClass(f),
    bold: textClass(f, 'font-bold'),
    label: textClass(label, 'font-bold'),
    loud: textClass(Math.round(f * 1.2), 'font-bold'),
    name: textClass(Math.round(f * 1.45), 'font-bold'),
    phone: textClass(Math.round(f * 1.15), 'font-bold'),
    labelGap: Math.max(1, Math.round(f * 0.15)),
    lineGap: Math.round(f * 0.1),
    sectionGap: Math.round(f * 0.8),
    contactGap: Math.round(f * 0.5),
    boxPad: Math.round(f * 0.45),
    border: Math.max(2, Math.round(f * 0.18)),
    icon: lineHeight(label),
    qrGap: Math.round(f * 0.6),
  }
}

// Texts to measure, each set in a class list at a width.
type Ask = { text: string; cls: string; width: number }

// The frame's typesetting, one call per class list and width; a runtime
// without it (before FrameOS 2026.11.12) gets a careful estimate.
const measure = (asks: Ask[]): number[] => {
  const heights: number[] = new Array(asks.length).fill(0)
  const groups = new Map<string, number[]>()
  asks.forEach((ask, i) => {
    const key = `${ask.cls}|${ask.width}`
    const list = groups.get(key)
    if (list) list.push(i)
    else groups.set(key, [i])
  })
  const native = typeof frameos !== 'undefined' && typeof frameos.measureText === 'function'
  for (const list of groups.values()) {
    const { cls: className, width } = asks[list[0]]
    const texts = list.map((i) => asks[i].text)
    const got = native ? frameos.measureText(texts, { className, width: Math.max(1, Math.floor(width)) }) : null
    list.forEach((i, j) => {
      heights[i] = got && typeof got[j] === 'number' ? got[j] : estimate(texts[j], className, width)
    })
  }
  return heights
}

const estimate = (text: string, className: string, width: number): number => {
  const size = Number(/text-\[(\d+)px\]/.exec(className)?.[1] ?? 16)
  const perLine = Math.max(1, Math.floor(width / (size * 0.62)))
  let lines = 1
  let used = 0
  for (const word of text.split(' ')) {
    const n = word.length + (used > 0 ? 1 : 0)
    if (used > 0 && used + n > perLine) {
      lines += 1 + Math.floor(word.length / perLine)
      used = word.length % perLine
    } else used += n
  }
  return lines * lineHeightOf(className)
}

// Whether a text set at a size stays on one line of a width.
export const fitsLine = (text: string, width: number, size: number, weight = 'font-bold'): boolean => {
  const className = textClass(size, weight)
  return width > 0 && measure([{ text, cls: className, width }])[0] <= lineHeightOf(className)
}

// The size, from start down to min, at which a text stays on one line.
export const fitLine = (text: string, width: number, start: number, min: number, weight = 'font-bold'): number => {
  for (let size = start; size > min; size -= Math.max(1, Math.round(size * 0.06))) {
    if (fitsLine(text, width, size, weight)) return size
  }
  return min
}

// The longest words of a text: each must fit on a line of its own.
const longWords = (text: string, count = 3): string[] =>
  Array.from(new Set(text.split(' ').filter((word) => word.length > 4)))
    .sort((a, b) => b.length - a.length)
    .slice(0, count)

// A contact's first line: its name and how they are related.
export const nameLine = (contact: Contact): string =>
  contact.name && contact.relation ? `${contact.name} (${contact.relation})` : contact.name || contact.relation

// The words under a contact's QR code in a row of them: the first name, with
// a title before it ("Dr. Jo"), else the relation.
export const captionOf = (contact: Contact, j: number): string => {
  const words = contact.name.split(' ').filter((word) => word !== '')
  const titles = words.findIndex((word) => !word.endsWith('.'))
  if (titles >= 0) return words.slice(0, titles + 1).join(' ')
  return contact.relation || `Contact ${j + 1}`
}

// The person's line under the name: born, blood type, organ donor.
export const factsLine = (card: Card): string => card.facts.map((fact) => `${fact.label}: ${fact.value}`).join(' · ')

export const dropNote = (dropped: string[]) => `No room on this screen for: ${dropped.join(', ')}`

// What there is room for: the width, the height under the header, one column
// or two, the QR codes' side (0 for none) and which contacts have one.
export type Room = {
  width: number
  height: number
  twoColumns: boolean
  columnGap: number
  qr: number
  qrRows: boolean[]
}

// Where the contacts' QR codes go: beside each contact, in a row under the
// list (each with the contact's name under it), or nowhere.
export type QrPlace = 'beside' | 'below' | 'none'

export type Plan = {
  sizes: Sizes
  columns: Section[][]
  columnWidth: number
  // The QR codes' side and where they go.
  qr: number
  place: QrPlace
  fits: boolean
  dropped: string[]
}

// Whether contact j gets a QR code: it has a number, and the scene made one.
export const hasQr = (room: Room, qr: number, contact: Contact, j: number) => qr > 0 && !!contact.tel && !!room.qrRows[j]

// The width of a contact's words: the column, less a QR code's room beside it.
export const contactWords = (place: QrPlace, qr: number, column: number, s: Sizes) =>
  place === 'beside' ? column - qr - s.qrGap : column

// The heights of the person, each section, and the note of what was left
// out, at the sizes s; whether every long word and phone stays whole; and
// where the QR codes go.
const heightsAt = (card: Card, sections: Section[], s: Sizes, full: number, column: number, room: Room, qr: number, dropped: string[]) => {
  const asks: Ask[] = []
  // What must stay on one line: for every arrangement (""), or only for one.
  const checks: { at: number; place: string }[] = []
  const ask = (text: string, className: string, width: number, place = '', oneLine = false) => {
    asks.push({ text, cls: className, width })
    const at = asks.length - 1
    if (oneLine) checks.push({ at, place })
    else {
      for (const word of longWords(text)) {
        asks.push({ text: word, cls: className, width })
        checks.push({ at: asks.length - 1, place })
      }
    }
    return at
  }
  const name = card.name ? ask(card.name, s.name, full) : -1
  const facts = card.facts.length ? ask(factsLine(card), s.bold, full) : -1
  const note = dropped.length ? ask(dropNote(dropped), s.label, full) : -1
  type Row = { name: number; phone: number }
  const rowsAt = (contacts: Contact[], width: number, place: string): Row[] =>
    contacts.map((contact) => {
      const line = nameLine(contact)
      return {
        name: line ? ask(line, s.bold, width, place) : -1,
        phone: contact.phone ? ask(contact.phone, s.phone, width, place, true) : -1,
      }
    })
  const per = sections.map((section) => {
    const inner = section.loud ? column - 2 * s.border - 2 * s.boxPad : column
    const label = ask(section.label.toUpperCase(), s.label, inner - (section.loud ? s.icon + 2 * s.labelGap : 0))
    const lines = section.contacts ? [] : section.lines.map((line) => ask(line, section.loud ? s.loud : s.body, inner))
    const withQr = section.contacts ? section.contacts.map((contact, j) => hasQr(room, qr, contact, j)) : []
    const anyQr = withQr.some((on) => on)
    const plain = section.contacts ? rowsAt(section.contacts, column, 'plain') : []
    const beside = section.contacts && anyQr ? rowsAt(section.contacts, column - qr - s.qrGap, 'beside') : []
    return { label, lines, withQr, anyQr, plain, beside }
  })
  const got = measure(asks)
  const whole = (place: string) => checks.every((check) => (check.place !== '' && check.place !== place) || got[check.at] <= lineHeightOf(asks[check.at].cls))
  const rowHeight = (row: Row) => (row.name >= 0 ? got[row.name] : 0) + (row.phone >= 0 ? got[row.phone] : 0)
  let unbroken = whole('')
  let place: QrPlace = 'none'
  const personHeight = (name >= 0 ? got[name] : 0) + (facts >= 0 ? got[facts] + (name >= 0 ? s.lineGap : 0) : 0)
  const heights = per.map((p, i) => {
    let h = got[p.label] + s.labelGap
    p.lines.forEach((at, j) => {
      h += got[at] + (j > 0 ? s.lineGap : 0)
    })
    if (sections[i].loud) h += 2 * s.border + 2 * s.boxPad
    if (!sections[i].contacts) return h
    // The contacts: the list alone, with a row of QR codes under it, or with
    // each code beside its contact, whichever is shortest.
    const gaps = (p.plain.length - 1) * s.contactGap
    const list = p.plain.reduce((sum, row) => sum + rowHeight(row), 0) + gaps
    const options: { place: QrPlace; height: number }[] = []
    if (whole('plain')) options.push({ place: 'none', height: list })
    if (p.anyQr) {
      const codes = p.withQr.filter((on) => on).length
      if (whole('plain') && codes * qr + (codes - 1) * s.qrGap <= column) {
        options.push({ place: 'below', height: list + s.contactGap + qr + s.labelGap + lineHeightOf(s.label) })
      }
      if (whole('beside')) {
        const height = p.beside.reduce((sum, row, j) => sum + Math.max(rowHeight(row), p.withQr[j] ? qr : 0), 0) + gaps
        options.push({ place: 'beside', height })
      }
    }
    const withCodes = options.filter((option) => option.place !== 'none')
    const best = (withCodes.length ? withCodes : options).reduce((a, b) => (b.height < a.height ? b : a), { place: 'none' as QrPlace, height: Infinity })
    if (best.height === Infinity) {
      unbroken = false
      return h + list
    }
    place = best.place
    return h + best.height
  })
  return { personHeight, heights, noteHeight: note >= 0 ? got[note] : 0, unbroken, place }
}

// The sections in two columns. Read down the left one and then the right,
// split where the taller of the two is shortest: the allergies and the
// contacts usually on the left, the rest on the right. When that leaves one
// column much taller (a contact list with QR codes), each section goes into
// the column that is shorter so far instead, each column still in the
// card's order.
const intoColumns = (sections: Section[], heights: number[], gap: number) => {
  const stack = (from: number, to: number) =>
    heights.slice(from, to).reduce((sum, h, i) => sum + h + (i > 0 ? gap : 0), 0)
  let split = 1
  let height = Infinity
  for (let k = 1; k < sections.length; k++) {
    const taller = Math.max(stack(0, k), stack(k, sections.length))
    if (taller < height) {
      height = taller
      split = k
    }
  }
  const balanced: Section[][] = [[], []]
  const used = [0, 0]
  sections.forEach((section, i) => {
    const c = used[1] < used[0] ? 1 : 0
    used[c] += (balanced[c].length ? gap : 0) + heights[i]
    balanced[c].push(section)
  })
  const even = Math.max(used[0], used[1])
  if (even < height * 0.92) return { columns: balanced, height: even }
  return { columns: [sections.slice(0, split), sections.slice(split)], height }
}

// The card at body size f: its columns, and whether it fits the room.
const layoutAt = (card: Card, sections: Section[], f: number, room: Room, qr: number, dropped: string[]) => {
  const s = sizesFor(f)
  const two = room.twoColumns && sections.length > 1
  const columnWidth = two ? Math.floor((room.width - room.columnGap) / 2) : room.width
  const measured = heightsAt(card, sections, s, room.width, columnWidth, room, qr, dropped)
  let columns: Section[][] = [sections]
  let body = measured.heights.reduce((sum, h, i) => sum + h + (i > 0 ? s.sectionGap : 0), 0)
  if (two) {
    const split = intoColumns(sections, measured.heights, s.sectionGap)
    columns = split.columns
    body = split.height
  }
  const parts = [measured.personHeight, body, measured.noteHeight].filter((h) => h > 0)
  const total = parts.reduce((sum, h) => sum + h, 0) + Math.max(0, parts.length - 1) * s.sectionGap
  return { sizes: s, columns, columnWidth, place: measured.place, fits: measured.unbroken && total <= room.height }
}

// The largest body size from lo to hi at which the card fits; lo when none does.
const largest = (card: Card, sections: Section[], room: Room, qr: number, lo: number, hi: number, dropped: string[]) => {
  let best = lo
  let fits = false
  let a = lo
  let b = hi
  while (a <= b) {
    const mid = (a + b) >> 1
    if (layoutAt(card, sections, mid, room, qr, dropped).fits) {
      best = mid
      fits = true
      a = mid + 1
    } else b = mid - 1
  }
  return { f: best, fits }
}

// The card's plan for the room: the largest type that fits, from `lo` up,
// with the QR codes while they cost the type little (or the type stays
// large anyway); when even `lo` does not fit, the last sections left out
// (never the allergies or the contacts) and named at the bottom, and only
// then type smaller than `lo`, down to `least`.
export const planCard = (card: Card, room: Room, least: number, lo: number, hi: number): Plan => {
  let sections = card.sections
  const dropped: string[] = []
  let qr = room.qr
  let found = largest(card, sections, room, 0, lo, hi, dropped)
  if (qr > 0) {
    const tried = largest(card, sections, room, qr, lo, hi, dropped)
    if (tried.fits && tried.f >= 14 && (tried.f >= found.f * 0.85 || tried.f >= 24)) found = tried
    else qr = 0
  }
  while (!found.fits && sections.length > 0) {
    const last = sections[sections.length - 1]
    if (last.loud || last.contacts) break
    dropped.unshift(last.label)
    sections = sections.slice(0, -1)
    found = largest(card, sections, room, qr, lo, hi, dropped)
  }
  if (!found.fits && least < lo) found = largest(card, sections, room, qr, least, lo - 1, dropped)
  const done = layoutAt(card, sections, found.f, room, qr, dropped)
  const place = qr > 0 ? done.place : 'none'
  return { sizes: done.sizes, columns: done.columns, columnWidth: done.columnWidth, qr: place === 'none' ? 0 : qr, place, fits: found.fits, dropped }
}

