import { get } from './app'
import { cardOf, parseContact, parseContacts, telOf } from './card'
import { captionOf, nameLine } from './fit'

// Everything a drawn tree says, as one text, and every element of a kind.
const textIn = (node: any): string => {
  if (node === null || node === undefined || typeof node === 'boolean') return ''
  if (typeof node === 'string' || typeof node === 'number') return String(node)
  if (Array.isArray(node)) return node.map(textIn).join('')
  return textIn(node.props?.children)
}
const elementsIn = (node: any, type: string, found: any[] = []): any[] => {
  if (!node || typeof node !== 'object') return found
  if (Array.isArray(node)) {
    node.forEach((child) => elementsIn(child, type, found))
    return found
  }
  if (node.type === type) found.push(node)
  elementsIn(node.props?.children, type, found)
  return found
}

const FILLED = {
  title: 'In case of emergency',
  emergencyNumber: '112',
  name: 'Alex Example',
  born: '4 May 1980',
  allergies: 'Penicillin\nPeanuts',
  contacts: 'Sam Example, partner, +32 470 12 34 56\nRobin Example, sister, 0470 98 76 54',
  conditions: 'Type 1 diabetes',
  medications: 'Insulin, with meals',
  bloodType: 'O+',
  organDonor: 'Yes',
  doctor: 'Dr. Lee, 02 555 01 00',
  notes: 'Spare key with the neighbor at number 12',
}

const qrRef = (id: number) => ({ __frameosType: 'imageRef', id, width: 72, height: 72 })

describe('a contact line', () => {
  it('reads name, relation and phone', () => {
    expect(parseContact('Sam Example, partner, +32 470 12 34 56')).toEqual({
      name: 'Sam Example', relation: 'partner', phone: '+32 470 12 34 56', tel: 'tel:+32470123456',
    })
  })

  it('takes the phone where it is, and keeps the rest as the relation', () => {
    expect(parseContact('Dr. Lee, 555-0100')).toEqual({ name: 'Dr. Lee', relation: '', phone: '555-0100', tel: 'tel:5550100' })
    expect(parseContact('Kim, neighbor, upstairs, (555) 010-0199')).toEqual({
      name: 'Kim', relation: 'neighbor, upstairs', phone: '(555) 010-0199', tel: 'tel:5550100199',
    })
    expect(parseContact('+1 (555) 010-0199, Jo, brother').tel).toBe('tel:+15550100199')
    expect(parseContact('+1 (555) 010-0199, Jo, brother').name).toBe('Jo')
  })

  it('finds a number at the end of a line with no commas', () => {
    expect(parseContact('Jamie Example 0470 12 34 56')).toEqual({
      name: 'Jamie Example', relation: '', phone: '0470 12 34 56', tel: 'tel:0470123456',
    })
    expect(parseContact('+44 20 7946 0000')).toEqual({ name: '', relation: '', phone: '+44 20 7946 0000', tel: 'tel:+442079460000' })
  })

  it('leaves a line without a number as a name', () => {
    expect(parseContact('Neighbor Kim, flat 2')).toEqual({ name: 'Neighbor Kim', relation: 'flat 2', phone: '', tel: '' })
  })

  it('is named under its QR code by first name, a title kept', () => {
    expect(captionOf(parseContact('Sam Example, partner, 555 0100'), 0)).toBe('Sam')
    expect(captionOf(parseContact('Dr. Jo Sample, family doctor, 02 555 01 00'), 1)).toBe('Dr. Jo')
    expect(captionOf(parseContact('+44 20 7946 0000'), 2)).toBe('Contact 3')
    expect(nameLine(parseContact('Sam Example, partner, 555 0100'))).toBe('Sam Example (partner)')
  })

  it('skips empty lines and extra space', () => {
    const contacts = parseContacts('  Sam ,  partner , 555 0100 \r\n\r\n\n Robin, 555 0101  ')
    expect(contacts.map((c) => c.name)).toEqual(['Sam', 'Robin'])
    expect(contacts[0].relation).toBe('partner')
    expect(telOf(contacts[1].phone)).toBe('tel:5550101')
  })
})

describe('the card', () => {
  it('shows only what is filled, allergies first and loud', () => {
    const card = cardOf({ allergies: 'Bee stings', notes: 'Has a dog', contacts: 'Sam, 555 0100', doctor: '' })
    expect(card.sections.map((s) => s.key)).toEqual(['allergies', 'contacts', 'notes'])
    expect(card.sections[0].loud).toBe(true)
    expect(card.sections[2].loud).toBeFalsy()
    expect(card.empty).toBe(false)
  })

  it('keeps the order a helper reads in, whatever is filled', () => {
    const card = cardOf(FILLED)
    expect(card.sections.map((s) => s.key)).toEqual(['allergies', 'contacts', 'conditions', 'medications', 'doctor', 'notes'])
    expect(card.sections[0].lines).toEqual(['Penicillin', 'Peanuts'])
    expect(card.facts.map((f) => f.label)).toEqual(['Born', 'Blood type', 'Organ donor'])
  })

  it('is empty with nothing filled, and keeps 112 and the title until they are changed', () => {
    const card = cardOf({ title: '', name: '  ', allergies: '\n' })
    expect(card.empty).toBe(true)
    expect(card.title).toBe('In case of emergency')
    expect(card.number).toBe('112')
    expect(cardOf({ emergencyNumber: '' }).number).toBe('')
    expect(cardOf({ emergencyNumber: '911', name: 'Alex' }).number).toBe('911')
    // The title and the number alone are no card.
    expect(cardOf({ emergencyNumber: '911', title: 'ICE' }).empty).toBe(true)
  })
})

describe('drawing it', () => {
  it('says how to fill it in when it is empty', () => {
    const app = makeApp({ state: { title: 'In case of emergency', emergencyNumber: '112' } })
    const text = textIn(get(app, makeContext()))
    expect(text).toContain("Open the scene's settings to fill in this card")
    expect(text).toContain('112')
    expect(text).not.toContain('ALLERGIES')
  })

  it('draws the filled card, its phones as links and its QR codes beside them', () => {
    const app = makeApp({ state: FILLED, config: { qr1: qrRef(1), qr2: qrRef(2), qr3: qrRef(3) } })
    const tree = get(app, makeContext())
    const text = textIn(tree)
    expect(text).toContain('ALLERGIES')
    expect(text).toContain('Penicillin')
    expect(text).toContain('Alex Example')
    expect(text).not.toContain('Open the scene')
    const links = elementsIn(tree, 'a').map((a) => a.props.href)
    expect(links).toEqual(['tel:112', 'tel:+32470123456', 'tel:0470987654'])
    expect(elementsIn(tree, 'img').map((img) => img.props.src.id)).toEqual([1, 2])
    // The allergies come before the contacts.
    expect(text.indexOf('Penicillin')).toBeLessThan(text.indexOf('Sam Example'))
  })

  it('leaves the QR codes out on a small panel, and on a round one', () => {
    const small = makeApp({ state: FILLED, config: { qr1: qrRef(1), qr2: qrRef(2) }, frame: { width: 240, height: 320 } })
    const smallTree = get(small, makeContext())
    expect(elementsIn(smallTree, 'img').length).toBe(0)
    expect(textIn(smallTree)).toContain('Penicillin')
    const round = makeApp({ state: FILLED, config: { qr1: qrRef(1) }, frame: { width: 466, height: 466 } })
    const roundTree = get(round, makeContext({ round: true }))
    expect(elementsIn(roundTree, 'img').length).toBe(0)
    expect(textIn(roundTree)).toContain('EMERGENCY')
    expect(elementsIn(roundTree, 'a').map((a) => a.props.href)).toContain('tel:+32470123456')
  })

  it('names what had no room rather than cutting it off', () => {
    const lots = { ...FILLED, notes: Array.from({ length: 40 }, (_, i) => `Note line ${i + 1} about the house`).join('\n') }
    const app = makeApp({ state: lots, frame: { width: 480, height: 800 } })
    const text = textIn(get(app, makeContext()))
    expect(text).toContain('No room on this screen for: Notes')
    expect(text).not.toContain('Note line 1 ')
    expect(text).toContain('Penicillin')
    expect(text).toContain('Type 1 diabetes')
    // A small screen keeps the allergies and the contacts first.
    const small = makeApp({ state: lots, frame: { width: 240, height: 320 } })
    const smallText = textIn(get(small, makeContext()))
    expect(smallText).toMatch(/No room on this screen for: .*Notes$/)
    expect(smallText).toContain('Penicillin')
    expect(smallText).toContain('0470 98 76 54')
  })
})
